// Vertrag: contracts/n8n-flow.md, Abschnitt "Signatur-Pruefung".
// HMAC-SHA256 ueber die ROHEN Body-Bytes (Webhook-Option "Raw Body"),
// nie ueber neu serialisiertes JSON.
const crypto = require('crypto');

const secret = $env.WEAVE_DELEGATION_SECRET;
if (!secret) {
  throw new Error('WEAVE_DELEGATION_SECRET ist in n8n nicht gesetzt');
}

const item = $input.first();
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const expected = Buffer.from(crypto.createHmac('sha256', secret).update(raw).digest('hex'), 'utf8');
const received = Buffer.from(String(item.json.headers['x-weave-signature'] ?? ''), 'utf8');
const valid = received.length === expected.length && crypto.timingSafeEqual(received, expected);

if (!valid) {
  return [{ json: { signature_valid: false } }];
}

const body = JSON.parse(raw.toString('utf8'));
const toolsBaseUrl = String(body.tools_base_url ?? '').replace(/\/+$/, '');
if (!toolsBaseUrl) {
  throw new Error('tools_base_url fehlt im Webhook-Body (TOOLS_BASE_URL in Weave-Runtime setzen)');
}

return [{
  json: {
    signature_valid: true,
    message: body.message,
    history: Array.isArray(body.history) ? body.history : [],
    bot_id: body.bot_id,
    delegation_token: body.delegation_token,
    search_url: `${toolsBaseUrl}/api/v1/tools/search`,
  },
}];

// Baut aus den Weave-Treffern den Kontext fuer das LLM und die
// `sources` fuer die Antwort an Weave-Runtime (Schema: contracts/n8n-flow.md,
// Abschnitt "Response"). Nummer [n] im Kontext == sources[n-1].
const cfg = $('Konfiguration').first().json;
const hits = ($input.first().json.results ?? []).slice(0, cfg.top_k);

const context = hits
  .map((hit, i) => {
    const s = hit.source;
    const label = s.page ? `${s.document}, S. ${s.page}` : s.document;
    return `[${i + 1}] ${label}\n${hit.text}`;
  })
  .join('\n\n');

const sources = hits.map((hit) => {
  const s = hit.source;
  const pages = /^(\d+)(?:-(\d+))?$/.exec(s.page ?? '');
  return {
    source: '',
    document_id: s.document_id,
    chunk_id: s.chunk_id,
    original_filename: s.document,
    page_start: pages ? Number(pages[1]) : null,
    page_end: pages ? Number(pages[2] ?? pages[1]) : null,
    collection: s.collection ?? null,
  };
});

const history = cfg.history
  .filter((m) => (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string')
  .slice(-cfg.max_history);

const messages = [
  { role: 'system', content: cfg.system_prompt },
  ...history,
  { role: 'user', content: `Kontext:\n${context}\n\nFrage: ${cfg.message}` },
];

return [{
  json: {
    has_hits: hits.length > 0,
    sources,
    llm_url: `${cfg.llm_base_url.replace(/\/+$/, '')}/chat/completions`,
    llm_request: {
      model: cfg.llm_model,
      temperature: cfg.temperature,
      stream: false,
      messages,
    },
  },
}];

// OpenAI-kompatible Antwort -> {answer, sources} fuer Weave-Runtime.
const ctx = $('Kontext aufbauen').first().json;
const content = $input.first().json.choices?.[0]?.message?.content ?? '';

// Reasoning-Modelle (z. B. via vLLM/Ollama) liefern teils <think>-Bloecke mit.
const answer = String(content).replace(/<think>[\s\S]*?<\/think>/g, '').trim();
if (!answer) {
  throw new Error('LLM-Endpunkt lieferte keine Antwort');
}

return [{ json: { answer, sources: ctx.sources } }];
